/* opengym-api — schema.
 *
 * One DDL per engine. The two are kept deliberately close so a reviewer can
 * see they describe the same tables: the column names, types and defaults
 * are identical, and only the engine's own boolean handling differs.
 *
 * Rules that keep this portable:
 *   - ids are generated by the application (base64url), never by an
 *     AUTOINCREMENT/IDENTITY column. A sequence is the one thing that would
 *     differ structurally between engines, and the app does not need one.
 *   - booleans are stored as 0/1 integers, because SQLite has no boolean
 *     type and INTEGER is accepted by both. A later Postgres migration can
 *     cast the column to boolean without touching the application.
 *   - timestamps are ISO-8601 strings, not a date type. They are only ever
 *     compared for equality or ordering, which both engines do identically
 *     on ISO text, and it keeps the JSON import byte-exact.
 *   - the per-user training state is a JSON document in a TEXT column. In
 *     Postgres the same column can become `jsonb` for indexing; the
 *     application never sees the difference because the repository parses
 *     and serialises it.
 */
export const SQLITE_SCHEMA = `
CREATE TABLE IF NOT EXISTS users (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  password_hash TEXT,
  admin         INTEGER NOT NULL DEFAULT 0,
  disabled      INTEGER NOT NULL DEFAULT 0,
  session_ver   INTEGER NOT NULL DEFAULT 0,
  created       TEXT,
  invited_by    TEXT,
  last_reminder TEXT
);
CREATE INDEX IF NOT EXISTS idx_users_name ON users(name);

CREATE TABLE IF NOT EXISTS creds (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL,
  public_key TEXT NOT NULL,
  counter    INTEGER NOT NULL DEFAULT 0,
  transports TEXT
);
CREATE INDEX IF NOT EXISTS idx_creds_user ON creds(user_id);

CREATE TABLE IF NOT EXISTS subs (
  endpoint TEXT PRIMARY KEY,
  user_id  TEXT NOT NULL,
  keys     TEXT NOT NULL,
  created  TEXT
);
CREATE INDEX IF NOT EXISTS idx_subs_user ON subs(user_id);

CREATE TABLE IF NOT EXISTS invites (
  code       TEXT PRIMARY KEY,
  note       TEXT,
  created_by TEXT,
  created    TEXT,
  used_by    TEXT,
  used_at    TEXT,
  revoked    INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS state (
  uid  TEXT PRIMARY KEY,
  json TEXT NOT NULL
);
`;

/* Same tables, same columns. The only difference is that Postgres has a real
 * boolean type, so the flag columns can be BOOLEAN here. The repository binds
 * 0/1, and Postgres accepts 0/1 for a boolean column, so the same queries
 * work unchanged against either schema.
 */
export const POSTGRES_SCHEMA = `
CREATE TABLE IF NOT EXISTS users (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  password_hash TEXT,
  admin         BOOLEAN NOT NULL DEFAULT FALSE,
  disabled      BOOLEAN NOT NULL DEFAULT FALSE,
  session_ver   INTEGER NOT NULL DEFAULT 0,
  created       TEXT,
  invited_by    TEXT,
  last_reminder TEXT
);
CREATE INDEX IF NOT EXISTS idx_users_name ON users(name);

CREATE TABLE IF NOT EXISTS creds (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL,
  public_key TEXT NOT NULL,
  counter    INTEGER NOT NULL DEFAULT 0,
  transports TEXT
);
CREATE INDEX IF NOT EXISTS idx_creds_user ON creds(user_id);

CREATE TABLE IF NOT EXISTS subs (
  endpoint TEXT PRIMARY KEY,
  user_id  TEXT NOT NULL,
  keys     TEXT NOT NULL,
  created  TEXT
);
CREATE INDEX IF NOT EXISTS idx_subs_user ON subs(user_id);

CREATE TABLE IF NOT EXISTS invites (
  code       TEXT PRIMARY KEY,
  note       TEXT,
  created_by TEXT,
  created    TEXT,
  used_by    TEXT,
  used_at    TEXT,
  revoked    BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS state (
  uid  TEXT PRIMARY KEY,
  json TEXT NOT NULL
);
`;

export function schemaFor(driver) {
  if (driver === 'postgres') return POSTGRES_SCHEMA;
  return SQLITE_SCHEMA;
}
